<script lang="ts">
  let{packages=[],revisionId}:{packages?:any[];revisionId:string}=$props();
  const version=(report:any,id:string)=>report.artifacts?.find((a:any)=>a.documentId===id)?.documentVersionId;
  const file=(report:any,id:string)=>`/api/v1/documents/${id}/download?version=${version(report,id)}`;
</script>
{#if packages.length}<div class="packages"><h3>Archivierte Fertigungspakete</h3>{#each packages as packet}{@const report=packet.validation_report??{}}{@const ready=packet.package_ready&&report.zipDocumentId&&report.manifestDocumentId&&report.renderWidth>=3840&&report.renderHeight>=2160&&['pdfDocumentId','bomDocumentId','renderDocumentId'].every(key=>version(report,report[key]))}
  <article><strong>{ready?'Vollständiges Paket bereit':packet.status==='blocked'?'Paket noch gesperrt':'Unterlagen werden zusammengestellt'}</strong><small>{packet.revision_id===revisionId?'Aktueller Planstand':'Früherer, eingefrorener Planstand'}</small>
    {#if report.message}<p>{report.message}</p>{/if}{#if packet.last_error}<p>{packet.last_error}</p>{/if}
    {#if ready}<p>Technische Zeichnung, Stückliste und {report.renderWidth} × {report.renderHeight} Pixel gehören zu derselben freigegebenen Revision.</p><a data-sveltekit-reload download class="primary" href={`/api/v1/documents/${report.zipDocumentId}/download?version=${report.zipDocumentVersionId}`}>Fertigungspaket herunterladen</a><div class="links"><a data-sveltekit-reload download href={`/api/v1/documents/${report.manifestDocumentId}/download?version=${report.manifestDocumentVersionId}`}>Inhaltsnachweis</a><a data-sveltekit-reload download href={file(report,report.pdfDocumentId)}>Zeichnung</a><a data-sveltekit-reload download href={file(report,report.bomDocumentId)}>Stückliste</a><a data-sveltekit-reload download href={file(report,report.renderDocumentId)}>Ansicht</a></div>{/if}
  </article>{/each}</div>{/if}
<style>.packages{padding-top:20px;margin-top:20px;border-top:1px solid var(--line)}.packages h3{font-size:12px;font-weight:500;color:var(--muted);margin:0 0 15px}article{padding:14px 0;border-bottom:1px solid var(--line);font-size:11px}strong{font-weight:500;color:var(--forest);display:block;line-height:1.7}small{display:block;margin-top:5px;font-size:10px;color:var(--muted)}p{font-size:11px;line-height:1.75;color:var(--muted);margin:10px 0}.primary{display:block;background:var(--forest);color:var(--on-accent,#fff);padding:12px;border-radius:4px;text-align:center;text-decoration:none;font-size:11px;line-height:1.5;margin:13px 0}.links{display:flex;flex-wrap:wrap;gap:9px}.links a{color:var(--forest);font-size:10px;padding:5px 0}a:focus-visible{outline:2px solid var(--forest);outline-offset:3px}</style>
